// Generated by `just generate` from `src/plugins/claudetto/slices/ground/adapters/check.ts`. Edit the source and run `just generate`.
// `check(event, prior)` for the `replay` script of `claudetto-sessions`: the same source check on a recorded call, with no engine.
// `event` is a `PreToolUse` event, and `prior` holds the transcript rows before the call.
// The files are read from the disk as it is now, so a file that is gone gives a deny for a `file:line` reference.

import path from "node:path";
import {
  type Files,
  findUnsourced,
  type Msg,
  neededFiles,
} from "../domain/claims.ts";
import { type PlanCall, planText } from "../domain/plan.ts";

interface Block {
  type?: string;
  text?: string;
  name?: string;
  content?: unknown;
}
interface Row {
  type?: string;
  message?: { content?: Block[] | string };
}

const read = (cwd: string, file: string): Promise<string | null> =>
  Bun.file(path.resolve(cwd, file))
    .text()
    .catch(() => null);

/** The text of a tool result, which is a string or a list of text blocks. */
const resultText = (content: unknown): string =>
  typeof content === "string"
    ? content
    : Array.isArray(content)
      ? content.map((b: Block) => b.text ?? "").join("\n")
      : "";

const msgOf = (row: Row): Msg | null => {
  if (row.type !== "user" && row.type !== "assistant") return null;
  const c = row.message?.content;
  const blocks: Block[] =
    typeof c === "string" ? [{ type: "text", text: c }] : (c ?? []);
  return {
    role: row.type,
    text: blocks
      .filter((b) => b.type === "text")
      .map((b) => b.text)
      .join("\n"),
    results: blocks
      .filter((b) => b.type === "tool_result")
      .map((b) => resultText(b.content)),
    bash: blocks.filter((b) => b.type === "tool_use" && b.name === "Bash")
      .length,
  };
};

export const check = async (
  event: {
    tool_name: string;
    tool_input: Omit<PlanCall, "tool"> & { old_string?: string };
    cwd?: string;
  },
  prior: Row[],
): Promise<{ decision: "block"; reason: string } | undefined> => {
  const input = event.tool_input ?? {};
  const text = planText({ tool: event.tool_name, ...input });
  if (text === null) return undefined;
  const cwd = event.cwd ?? ".";
  const files: Files = Object.fromEntries(
    await Promise.all(
      neededFiles(text).map(async (n) => [n, await read(cwd, n)] as const),
    ),
  );
  const msgs = prior.map(msgOf).filter((m): m is Msg => m !== null);
  const claims = findUnsourced(
    text,
    msgs,
    files,
    `${(await read(cwd, input.file_path ?? "")) ?? ""}\n${input.old_string ?? ""}`,
  );
  return claims.length > 0
    ? { decision: "block", reason: claims.join("\n") }
    : undefined;
};
